// План: specs/profile.md, блок 4 (4.2). Кейс: .qa/tests/profile/PRF-005.md (#3ec77d).
// Несколько ролей: клиент (04) загружает фото профиля → נותן שירות (05) в общей сделке видит то же фото в «הצדדים בעסקה».
// Меняет профиль общего аккаунта 04 → @data; в конце фото удаляется («הסרת התמונה» → «שמירה»).
// Записан 04.11 без прогона: селекторы выбора фото / «הסרת התמונה» / «שמירה» подтвердить при первом /qa-regress.
import { test, expect } from '../../fixtures';
import type { Page } from '@playwright/test';
import * as fs from 'fs';
import * as path from 'path';

test.describe.configure({ mode: 'serial', retries: 0 });

const IMAGE = path.resolve(__dirname, '../../../test-assets/qa-business-doc.png');
const CREATED_LOG = path.resolve(__dirname, '../../qa-auto-created.jsonl');
const CLIENT_NAME = 'יונתן לוי';

/** Общая сделка 04↔05: QA_SHARED_DEAL_ID или последняя созданная автотестами (все — 04→05). */
function sharedDealId(): string | undefined {
  if (process.env.QA_SHARED_DEAL_ID) return process.env.QA_SHARED_DEAL_ID;
  if (!fs.existsSync(CREATED_LOG)) return undefined;
  const lines = fs.readFileSync(CREATED_LOG, 'utf8').trim().split('\n').filter(Boolean);
  for (let i = lines.length - 1; i >= 0; i--) {
    try {
      const e = JSON.parse(lines[i]);
      if (e.dealId) return e.dealId as string;
    } catch {
      /* пропустить битую строку */
    }
  }
  return undefined;
}

/** «עריכת פרופיל» → выбрать картинку → «שמירה». */
async function uploadPhoto(page: Page) {
  await page.goto('/profile/edit');
  const chooser = page.waitForEvent('filechooser');
  await page.getByText(/תמונת פרופיל/).first().click();
  const gallery = page.getByText(/בחירה מהגלריה|בחירת תמונה/).first();
  if (await gallery.isVisible().catch(() => false)) await gallery.click();
  await (await chooser).setFiles(IMAGE);
  await page.getByRole('button', { name: 'שמירה' }).click();
}

/** Очистка: «הסרת התמונה» → «שמירה». */
async function removePhoto(page: Page) {
  await page.goto('/profile/edit');
  const remove = page.getByRole('button', { name: /הסרת התמונה/ });
  if (await remove.first().isVisible().catch(() => false)) {
    await remove.first().click();
    await page.getByRole('button', { name: 'שמירה' }).click();
  }
}

function profileImage(page: Page) {
  return page.locator('img[src*="/profile-images/"]').first();
}

test.describe('תמונת פרופיל — גלויה לצד השני בעסקה', () => {
  test('05 רואה את תמונת הפרופיל של 04 ב"הצדדים בעסקה" — אותה כתובת profile-images @iphone @data #3ec77d', async ({ asUser }) => {
    const dealId = sharedDealId();
    test.skip(!dealId, 'Нужна общая сделка 04↔05: задай QA_SHARED_DEAL_ID=<id> (или запусти тесты, создающие сделки QA-AUTO-…).');

    const client = await asUser('client');
    const provider = await asUser('provider');

    try {
      // 1. Клиент загружает фото; адрес — публичное хранилище, не blob:.
      await uploadPhoto(client);
      await client.goto('/profile');
      await expect(profileImage(client)).toBeVisible();
      const src = (await profileImage(client).getAttribute('src')) ?? '';
      expect(src).toMatch(/^https:\/\/.+\/profile-images\//);

      // 2. Поставщик в общей сделке видит то же фото рядом с именем клиента.
      await provider.goto(`/deals/${dealId}`);
      await expect(provider.getByText('הצדדים בעסקה').first()).toBeVisible();
      await expect(provider.getByText(CLIENT_NAME).first()).toBeVisible();
      await expect(provider.locator(`img[src="${src}"]`).first()).toBeVisible();
    } finally {
      // 3. Очистка — фото общего аккаунта 04 удаляется.
      await removePhoto(client);
    }
  });
});
